SQL_COEFFICIENT_ACTIVE = 'select BRANCH name,sum(DEBTMAIN*kurus) portfel,sum(DATEDEBTINT*kurus) odenilmelifaiz,sum(PAYEDINT*kurus) odenilmish,\nsum(DEBTOVERINT*kurus) gecfaizmeb,sum(GECFAIZQALIQ*kurus) gec ,sum(GECFAIZQALIQ*kurus )/sum(DEBTMAIN*kurus) gf\n,sum(PAYEDINT*kurus) /sum(DATEDEBTINT*kurus)f\nfrom cm_report_f1 \n\n\ngroup by BRANCH\n\n\n\n\n/*select  f.name,sum(h.rest*o.ostat) portfel,sum(CM_COEFFICIENT.get_payint(p.id,:dat)*o.ostat) odenilmelifaiz,\nsum(CM_COEFFICIENT.get_payment(p.id,:dat)*o.ostat) odenilmish,sum(CM_COEFFICIENT.get_gec(p.id,:dat)*o.ostat) gec \n,sum(CM_COEFFICIENT.get_gec(p.id,:dat)*o.ostat)/sum(h.rest*o.ostat) gf,sum(CM_COEFFICIENT.get_gecfaiz(p.id,:dat)*o.ostat)gecfaizmeb,\nsum(CM_COEFFICIENT.get_payment(p.id,:dat)*o.ostat)/sum(CM_COEFFICIENT.get_payint(p.id,:dat)*o.ostat) f from \ncm_active_credits p,\ncm_history h,\nfilial f,\nsmart.OPERKURS o\nwhere \np.id=h.creditid and \nh.hdate = :dat and\np.branchid=f.id and\no.dat = :dat and  \np.currency=o.VAL_KOD -- and h.rest>0\n\n\n\n\n\n\ngroup by f.name*/'

# CM_coefficient/coefficientImpl.dfm:501 main
SQL_COEFFICIENT_MAIN = 'select BRANCH name,sum(DEBTMAIN*kurus) portfel,sum(DATEDEBTMAIN*kurus) odenilmeli ,sum(PAYEDMAIN*kurus) odenilmish,\nsum(ARTIQESAS*kurus) artiq,sum(nvl(DEBTOVERMAIN,0)*kurus) geces,\nsum(GECESASQALIQ*kurus) gec\nfrom cm_report_f1 \n\n\ngroup by BRANCH\n\n\n\n\n\n\n\n\n/*select  f.name,sum(h.rest*o.ostat) portfel ,sum(cm_coefficient.get_odenilmelirest(p.id,:dat)*o.ostat) odenilmeli ,\nsum(cm_coefficient.get_paymain(p.id,:dat)*o.ostat) odenilmish,\nsum(cm_coefficient.get_artiq(p.id,:dat)*o.ostat) artiq,sum(cm_coefficient.get_geces(p.id,:dat)*o.ostat) geces\n,sum(cm_coefficient.get_gecmain(p.id,:dat)*o.ostat) gec\nfrom \ncm_active_credits p,\ncm_history h,\nfilial f,\nsmart.OPERKURS o\nwhere \np.id=h.creditid and \nh.hdate = :dat and\np.branchid=f.id and\no.dat = :dat and\np.currency=o.VAL_KOD  --and h.rest>0\n\n\n\n\n\n\n\n\n\ngroup by f.name*/\n\n\n\n'

# CM_coefficient/coefficientImpl.dfm:587 OracleDataSet1
SQL_COEFFICIENT_ORACLEDATASET1 = 'select  f.name,sum(round(h.rest*o.ostat,2)) portfel,sum(round(CM_COEFFICIENT.get_payint(p.id,:dat)*o.ostat,2)) odenilmelifaiz,\nsum(round(CM_COEFFICIENT.get_payment(p.id,:dat)*o.ostat,2)) odenilmish,sum(round(CM_COEFFICIENT.get_gec(p.id,:dat)*o.ostat,2)) gec \n,sum(CM_COEFFICIENT.get_gec(p.id,:dat)*o.ostat)/sum(h.rest*o.ostat) gf,sum(CM_COEFFICIENT.get_gecfaiz(p.id,:dat)*o.ostat)gecfaizmeb,\nsum(CM_COEFFICIENT.get_payment(p.id,:dat)*o.ostat)/sum(CM_COEFFICIENT.get_payint(p.id,:dat)*o.ostat) f from \ncm_active_credits p,\ncm_history h,\nfilial f,\nsmart.OPERKURS o\nwhere \np.id=h.creditid and \nh.hdate = :dat and\np.branchid=f.id and\no.dat = :dat and  \np.currency=o.VAL_KOD -- and h.rest>0\n\n/*15*/\n\n\n\n\n\ngroup by f.name'

# CM_coefficient/coefficientImpl.dfm:660 OracleDataSet2
SQL_COEFFICIENT_ORACLEDATASET2 = 'select  f.name,sum(round(h.rest*o.ostat,2)) portfel ,sum(round(cm_coefficient.get_odenilmelirest(p.id,:dat)*o.ostat,2)) odenilmeli ,\nsum(round(cm_coefficient.get_paymain(p.id,:dat)*o.ostat,2)) odenilmish,\nsum(round(cm_coefficient.get_paymain(p.id,:dat)*o.ostat,2))-sum(round(cm_coefficient.get_odenilmelirest(p.id,:dat)*o.ostat,2)) artiq\n,sum(round(cm_coefficient.get_gecmain(p.id,:dat)*o.ostat,2)) gec\nfrom \ncm_active_credits p,\ncm_history h,\nsb_filial f,\nsmart.OPERKURS o\nwhere \np.id=h.creditid and \nh.hdate = :dat and\np.branchid=f.id and\no.dat = :dat and\np.currency=o.VAL_KOD  --and h.rest>0\n\n/*17*/\n\n\ngroup by f.name\n\n\n\n'

