# CM_DECA/DecaDataModuleImpl.dfm:19 OracleDataSet1
SQL_DECA_ORACLEDATASET1 = "SELECT\n   A.BOOROWERID AS ID,\n   A.NAME AS NAME,\n   A.COUNTRYCODE AS COUNTRCODE,\n   A.BANKRUPTEYSTATUS AS BNKSTATUS,\n   cm_deca.get_custdateofbirth(b.boorowerid) AS DATOFBIRTH, --dogum tarixi\n   cm_deca.get_custplaceofbirth(b.boorowerid) AS PLACEBIRTH, --dogum yeri\n   A.pincode AS PINCODE,\t\t\t--pin kod\n   A.guarantorid AS GID,\t--zamin id\n   a.guarantorname AS GNAME,\t--zamin ad\n   A.guarantorid2 AS GID2,\t--zamin id2\n   A.guarantorname2 AS GNAME2,\t--zamin ad2\n   A.guarantorid3 AS GID3,\t--zamin id3\n   A.guarantorname3 AS GNAME3,\t--zamin ad3\n   cm_deca.get_credittypes(b.id) CREDITTYPE,\t--kreditin tipi\n   cm_deca.get_lastcreditpayment(b.id) LASTPAYDAT,\t--sonuncu odenish tarixi\n   cm_deca.get_creditpaymentamount(b.id) MPAYAMOUNT,\t--ayliq odenish\n   cm_deca.get_reserveaccountostat(b.id) PROVISION,\t--ehtiyyat miqdari\n   A.FIRSTOWNERID AS ID2,\n   A.FIRSTOWNERNAME AS NAME2,\n   A.SECONDOWNERID AS ID3,\n   A.SECONDOWNERNAME AS NAME3,\n   A.THIRDOWNERID AS ID4,\n   A.THIRDOWNERNAME AS NAME4,\n   B.ID as InternalID, -- INTERNAL FIELD\n   CM_COMMON.AccountNumber_Get(c.LOANACCID) AS ACCOUNTNO ,\n   V.VAL_NAME AS CURRENCY,\n   cm_deca.get_creditinitialamount(b.id) AS INITIALSUM,\n   cm_deca.get_creditlineamount(b.id) AS CRDLINESUM,\n   D.REST + D.DUEREST AS DISOUSUM ,\n   B.ANNUALYINTERESTRATE AS RATE,\n   P.CODE AS PURPOSE,\n   TRUNC(MONTHS_BETWEEN(B.DUEDATEFIRSTCONTRACT,B.DATEOFCONCLUSION)) AS PERIODMONT ,\n   B.DATEOFCONCLUSION AS DATEGRANT,\n   B.DUEDATEFIRSTCONTRACT AS FIRSTCONTR,\n   DECODE(B.DUEDATELASTCONTRACT,null,B.DUEDATEFIRSTCONTRACT,B.DUEDATELASTCONTRACT) AS LASTCONTR,\n   CM_DECA.DueDaysCount(:HDATE , B.DUEDATEFIRSTCONTRACT,b.id) AS DAYSMAIN ,\n   CM_DECA.DueDaysCount(:HDATE , B.DUEDATEFIRSTCONTRACT,b.id) AS DAYSINTRST ,\n   D.DUEINTERESTREST+D.interestrest AS OIAPERIOD ,\n   CM_DECA.OiaForLastThreeMonths(:HDATE , B.DUEDATEFIRSTCONTRACT,D.DUEINTERESTREST) AS OIATHREE ,\n   0 AS PROLONGS ,\n   E.CODE AS CLASSCODE,\n   CM_DECA.Get_CreditStatus(B.ID,:HDATE) AS STATUSCODE ,\n   DECODE(G.TYPECODE,'000',null,G.TYPECODE) AS COLLCODE,\n   F.ANYINFOTODISTING AS INFDISTING,\n   D.PLEDGEPRICE  AS MARKETSUM ,\n   F.REGISTRYNO AS REGNO,\n   F.REGISTRYDATE AS REGDATE,\n   F.REGISTRYAGENCY AS REGAGENCY\nFROM\n   CM_BOOROWERINFO A\n , CM_ACCOUNTS C\n , CM_RESERVE_TYPES E\n , CM_GUARANTEE F\n , CM_PORTFOLIO B\n , CM_PLEDGES G\n , CM_HISTORY D\n , SB_OPERKURS O\n , SB_AVALUTE V\n , CM_CATEGORIES P\nWHERE\n     (A.CREDITID = B.ID)\n AND (C.CREDITID = B.ID)\n AND (D.CREDITID = B.ID)\n AND (E.ID = D.RESERVEID)\n AND (F.CREDITID = B.ID)\n AND (G.ID = F.PLEDGEID)\n AND (D.HDATE=:HDATE)\n AND ((B.CLOSEDATE IS NULL) or (B.CLOSEDATE between :EDATE and :HDATE) /*(B.CLOSEDATE >=:HDATE)*/)\n AND (O.DAT=:HDATE)\n AND (O.VAL_KOD=B.CURRENCY)\n--AND (O.OSTAT * B.CREDITLINEAMOUNT >= 1000)\n AND (V.VALUTE=B.CURRENCY)\n AND (B.DATEOFCONCLUSION<=:HDATE)\n-- AND (B.CLOSEDATE is not null)\n AND (P.ID = B.CUSTOMERTYPE) --and cm_deca.get_creditinitialamount(b.id)>0\n"

# CM_DECA/DecaDataModuleImpl.dfm:170 DecaData_tur
SQL_DECA_DECADATA_TUR = "SELECT\n   nvl(A.BOOROWERID,0) AS ID,\n   A.NAME AS NAME,\n   A.COUNTRYCODE AS COUNTRCODE,\n   A.BANKRUPTEYSTATUS AS BNKSTATUS,\n   to_char(cm_deca.get_custdateofbirth(b.boorowerid),'dd/mm/yyyy') AS DATOFBIRTH, --dogum tarixi\n   cm_deca.get_custplaceofbirth(b.boorowerid) AS PLACEBIRTH, --dogum yeri\n   A.pincode AS PINCODE,\t\t\t--pin kod\n   A.guarantorid AS GID,\t--zamin id\n   a.guarantorname AS GNAME,\t--zamin ad\n   A.guarantorid2 AS GID2,\t--zamin id2\n   A.guarantorname2 AS GNAME2,\t--zamin ad2\n   A.guarantorid3 AS GID3,\t--zamin id3\n   A.guarantorname3 AS GNAME3,\t--zamin ad3\n   cm_deca.get_credittypes(b.id) CREDITTYPE,\t--kreditin tipi\n   to_char(cm_deca.get_lastcreditpayment(b.id),'dd/mm/yyyy') LASTPAYDAT,\t--sonuncu odenish tarixi\n   cm_deca.get_creditpaymentamount(b.id) MPAYAMOUNT,\t--ayliq odenish\n  -- cm_deca.get_reserveaccountostat(b.id) PROVISION,\t--ehtiyyat miqdari\n   A.FIRSTOWNERID AS ID2,\n   A.FIRSTOWNERNAME AS NAME2,\n   A.SECONDOWNERID AS ID3,\n   A.SECONDOWNERNAME AS NAME3,\n   A.THIRDOWNERID AS ID4,\n   A.THIRDOWNERNAME AS NAME4,\n   B.ID as InternalID, -- INTERNAL FIELD\n   /*CM_COMMON.AccountNumber_Get(c.LOANACCID)*/  B.ID AS ACCOUNTNO ,\n   V.VAL_NAME AS CURRENCY,\n   cm_deca.get_creditinitialamount(b.id) AS INITIALSUM,\n   cm_deca.get_creditlineamount(b.id) AS CRDLINESUM,\n   D.REST + D.DUEREST AS DISOUSUM ,\n   B.ANNUALYINTERESTRATE AS RATE,\n   P.CODE AS PURPOSE,\n    decode(TRUNC(MONTHS_BETWEEN(B.DUEDATEFIRSTCONTRACT,B.DATEOFCONCLUSION)),0,1,TRUNC(MONTHS_BETWEEN(B.DUEDATEFIRSTCONTRACT,B.DATEOFCONCLUSION))) AS PERIODMONT ,\n  to_char( B.DATEOFCONCLUSION,'dd/mm/yyyy') AS DATEGRANT,\n  to_char( B.DUEDATEFIRSTCONTRACT,'dd/mm/yyyy') AS FIRSTCONTR,\n  to_char( DECODE(B.DUEDATELASTCONTRACT,null,B.DUEDATEFIRSTCONTRACT,B.DUEDATELASTCONTRACT),'dd/mm/yyyy') AS LASTCONTR,\n   CM_DECA.DueDaysCount(:RDAT , B.DUEDATEFIRSTCONTRACT,b.id) AS DAYSMAIN ,\n   CM_DECA.DueDaysCount(:RDAT , B.DUEDATEFIRSTCONTRACT,b.id) AS DAYSINTRST ,\n   D.DUEINTERESTREST+D.interestrest AS OIAPERIOD ,\n --  CM_DECA.OiaForLastThreeMonths(:RDAT , B.DUEDATEFIRSTCONTRACT,D.DUEINTERESTREST) AS OIATHREE ,\n   0 AS PROLONGS ,\n   E.CODE AS CLASSCODE,\n   CM_DECA.Get_CreditStatus(B.ID,:RDAT) AS STATUSCODE ,\n   to_char(DECODE(G.TYPECODE,'000',null,G.TYPECODE)) AS COLLCODE,\n   F.ANYINFOTODISTING AS INFDISTING,\n   D.PLEDGEPRICE AS MARKETSUM ,\n   F.REGISTRYNO AS REGNO,\n  to_char( F.REGISTRYDATE,'dd/mm/yyyy') AS REGDATE,\n   F.REGISTRYAGENCY AS REGAGENCY\nFROM\n   CM_BOOROWERINFO A\n , CM_ACCOUNTS C\n , CM_RESERVE_TYPES E\n , CM_GUARANTEE F\n , CM_PORTFOLIO B\n , CM_PLEDGES G\n , CM_HISTORY D\n , OPERKURS O\n , AVALUTE V\n , CM_CATEGORIES P\nWHERE\n     (A.CREDITID = B.ID)\n AND (C.CREDITID = B.ID)\n AND (D.CREDITID = B.ID)\n AND (E.ID = D.RESERVEID)\n AND (F.CREDITID(+) = B.ID)\n AND (G.ID(+) = F.PLEDGEID)\n AND (D.HDATE=:HDATE)\n AND ((B.CLOSEDATE IS NULL) or (B.CLOSEDATE between :EDATE and :HDATE) /*(B.CLOSEDATE >=:HDATE)*/)\n AND (O.DAT=:HDATE)\n AND (O.VAL_KOD=B.CURRENCY)\n--AND (O.OSTAT * B.CREDITLINEAMOUNT >= 1000)\n AND (V.VALUTE=B.CURRENCY)\n AND (B.DATEOFCONCLUSION<=:HDATE)\n AND (P.ID = B.CUSTOMERTYPE) --and cm_deca.get_creditinitialamount(b.id)>0\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n"

# CM_DECA/DecaDataModuleImpl.dfm:340 TagSettings
SQL_DECA_TAGSETTINGS = 'SELECT a.rowid, a.fieldname, a.tagfirst, a.taglast, a.tagprefix, a.tagsuffix,\n       a.alphafield, a.fieldgroup, a.num, a.usefield, a.parentgroup\n  FROM smart.cm_decasettings a\norder by num'

# CM_DECA/DecaDataModuleImpl.dfm:400 OracleDataSet2
SQL_DECA_ORACLEDATASET2 = "SELECT\n   A.BOOROWERID AS ID,\n   A.NAME AS NAME,\n   A.COUNTRYCODE AS COUNTRCODE,\n   A.BANKRUPTEYSTATUS AS BNKSTATUS,\n   cm_deca.get_custdateofbirth(b.boorowerid) AS DATOFBIRTH, --dogum tarixi\n   cm_deca.get_custplaceofbirth(b.boorowerid) AS PLACEBIRTH, --dogum yeri\n   A.pincode AS PINCODE,      --pin   kod\n   A.guarantorid AS GID,      --zamin id\n   a.guarantorname AS GNAME,  --zamin ad\n   A.guarantorid2 AS GID2,    --zamin id2\n   A.guarantorname2 AS GNAME2,--zamin ad2\n   A.guarantorid3 AS GID3,    --zamin id3\n   A.guarantorname3 AS GNAME3,--zamin ad3\n   cm_deca.get_credittypes(b.id) CREDITTYPE,    --kreditin tipi\n   cm_deca.get_lastcreditpayment(b.id) LASTPAYDAT,  --sonuncu odenish tarixi\n   cm_deca.get_creditpaymentamount(b.id) MPAYAMOUNT,    --ayliq odenish\n   cm_deca.get_reserveaccountostat(b.id) PROVISION, --ehtiyyat miqdari\n   /*A.FIRSTOWNERID*/'' AS ID2,\n  /* A.FIRSTOWNERNAME*/'' AS NAME2,\n   A.SECONDOWNERID AS ID3,\n   A.SECONDOWNERNAME AS NAME3,\n   A.THIRDOWNERID AS ID4,\n   A.THIRDOWNERNAME AS NAME4,\n   B.ID as InternalID, -- INTERNAL FIELD\n  /* CM_COMMON.AccountNumber_Get(c.LOANACCID)*/ b.id AS ACCOUNTNO ,\n   V.VAL_NAME AS CURRENCY,\n   cm_deca.get_creditinitialamount(b.id) AS INITIALSUM,\n   cm_deca.get_creditlineamount(b.id) AS CRDLINESUM,\n   D.REST + D.DUEREST AS DISOUSUM ,\n   B.ANNUALYINTERESTRATE AS RATE,\n   P.CODE AS PURPOSE,\n   TRUNC(MONTHS_BETWEEN(B.DUEDATEFIRSTCONTRACT,B.DATEOFCONCLUSION)) AS PERIODMONT ,\n   B.DATEOFCONCLUSION AS DATEGRANT,\n   B.DUEDATEFIRSTCONTRACT AS FIRSTCONTR,\n   DECODE(B.DUEDATELASTCONTRACT,null,B.DUEDATEFIRSTCONTRACT,B.DUEDATELASTCONTRACT) AS LASTCONTR,\n   CM_DECA.DueDaysCount('19-oct-2010' , B.DUEDATEFIRSTCONTRACT,b.id) AS DAYSMAIN ,\n   CM_DECA.DueDaysCount('19-oct-2010' , B.DUEDATEFIRSTCONTRACT,b.id) AS DAYSINTRST ,\n   D.DUEINTERESTREST+D.interestrest AS OIAPERIOD ,\n   CM_DECA.OiaForLastThreeMonths('19-oct-2010' , B.DUEDATEFIRSTCONTRACT,D.DUEINTERESTREST) AS OIATHREE ,\n   0 AS PROLONGS ,\n   E.CODE AS CLASSCODE,\n   CM_DECA.Get_CreditStatus(B.ID,'19-oct-2010') AS STATUSCODE ,\n   DECODE(G.TYPECODE,'000',null,G.TYPECODE) AS COLLCODE,\n   F.ANYINFOTODISTING AS INFDISTING,\n   D.PLEDGEPRICE * O.OSTAT AS MARKETSUM ,\n   F.REGISTRYNO AS REGNO,\n   F.REGISTRYDATE AS REGDATE,\n   F.REGISTRYAGENCY AS REGAGENCY\nFROM\n   CM_BOOROWERINFO A\n , CM_ACCOUNTS C\n , CM_RESERVE_TYPES E\n , CM_GUARANTEE F\n , CM_PORTFOLIO B\n , CM_PLEDGES G\n , CM_HISTORY D\n , SB_OPERKURS O\n , SB_AVALUTE V\n , CM_CATEGORIES P\nWHERE\n     (A.CREDITID = B.ID)\n AND (C.CREDITID = B.ID)\n AND (D.CREDITID = B.ID)\n AND (E.ID = D.RESERVEID)\n AND (F.CREDITID = B.ID)\n AND (G.ID = F.PLEDGEID)\n AND (D.HDATE='19-oct-2010')\n AND ((B.CLOSEDATE IS NULL) or (B.CLOSEDATE between '19-oct-2010' and '19-oct-2010'))\n AND (O.DAT='19-oct-2010')\n AND (O.VAL_KOD=B.CURRENCY)\n AND (V.VALUTE=B.CURRENCY)\n AND (B.DATEOFCONCLUSION<='19-oct-2010') \n AND (P.ID = B.CUSTOMERTYPE) and b.id=418"

# CM_DECA/DecaDataModuleImpl.dfm:544 OracleDataSet3
SQL_DECA_ORACLEDATASET3 = "SELECT a.rowid, a.fieldname, a.tagfirst, a.taglast, a.tagprefix, a.tagsuffix,\n       a.alphafield, a.fieldgroup, a.num, a.usefield, a.parentgroup\n  FROM smart.cm_decasettings a\n\nwhere a.fieldname not in('NAME5','REGAGSY1')\nand fieldname=:fname\n\norder by num"

# CM_DECA/DecaDataModuleImpl.dfm:576 OracleDataSet5_aqrar
SQL_DECA_ORACLEDATASET5_AQRAR = "SELECT\n   nvl(A.BOOROWERID,0) AS ID,\n   DECODE(A.NAME,'&','_',A.NAME)  AS NAME,\n   A.COUNTRYCODE AS COUNTRCODE,\n   A.BANKRUPTEYSTATUS AS BNKSTATUS,\n   to_char(cm_deca.get_custdateofbirth(b.boorowerid),'dd/mm/yyyy') AS DATOFBIRTH, --dogum tarixi\n   cm_deca.get_custplaceofbirth(b.boorowerid) AS PLACEBIRTH , --dogum yeri\n   A.pincode AS PINCODE,            --pin kod\n   g1.guarantorid AS GID,    --zamin id\n   g1.guarantorname AS GNAME,g1.cuntrycode GCUNTRYCODE,to_char(g1.dateofbirth,'dd/mm/yyyy')   GDATEOFBIRTH,g1.cuntry||' '||g1.city GPLACE,nvl(g1.PINCODE,' ') GPINCODE,    --zamin 1\n   g2.guarantorid AS GID2,  --zamin 2\n   g2.guarantorname AS GNAME2, g2.cuntrycode GCUNTRYCODE2,to_char(g2.dateofbirth,'dd/mm/yyyy') GDATEOFBIRTH2,g2.cuntry||' '||g2.city GPLACE2,nvl(g2.PINCODE,' ') GPINCODE2, --zamin 2\n   g3.guarantorid AS GID3,  --zamin id3\n   g3.guarantorname AS GNAME3, g3.cuntrycode GCUNTRYCODE3,to_char(g3.dateofbirth,'dd/mm/yyyy') GDATEOFBIRTH3,g3.cuntry||' '||g3.city GPLACE3,nvl(g3.PINCODE,' ') GPINCODE3, --zamin 3\n   cm_deca.get_credittypes(b.id) CREDITTYPE,    --kreditin tipi\n   to_char(cm_deca.get_lastcreditpayment(b.id),'dd/mm/yyyy') LASTPAYDAT,    --sonuncu odenish tarixi\n   cm_deca.get_creditpaymentamount(b.id) MPAYAMOUNT,    --ayliq odenish\n   cm_deca.get_reserveaccountostat(b.id) PROVISION, --ehtiyyat miqdari\n   A.FIRSTOWNERID AS ID2,\n   A.FIRSTOWNERNAME AS NAME2,\n   A.SECONDOWNERID AS ID3,\n   A.SECONDOWNERNAME AS NAME3,\n   A.THIRDOWNERID AS ID4,\n   A.THIRDOWNERNAME AS NAME4,\n   B.ID as InternalID, -- INTERNAL FIELD\n  /* CM_COMMON.AccountNumber_Get(c.LOANACCID)*/b.id AS ACCOUNTNO ,\n   V.VAL_NAME AS CURRENCY,\n   cm_deca.get_creditinitialamount(b.id) AS INITIALSUM,\n   cm_deca.get_creditlineamount(b.id) AS CRDLINESUM,\n   D.REST + D.DUEREST AS DISOUSUM ,\n   B.ANNUALYINTERESTRATE AS RATE,\n   P.CODE AS PURPOSE,\n   decode(TRUNC(MONTHS_BETWEEN(B.DUEDATEFIRSTCONTRACT,B.DATEOFCONCLUSION)),0,1,TRUNC(MONTHS_BETWEEN(B.DUEDATEFIRSTCONTRACT,B.DATEOFCONCLUSION))) AS PERIODMONT ,\n   to_char(B.DATEOFCONCLUSION,'dd/mm/yyyy') AS DATEGRANT,\n   to_char(nvl(b.duedatelastcontract,b.duedatefirstcontract),'dd/mm/yyyy') AS FIRSTCONTR,\n   to_char( DECODE(B.DUEDATELASTCONTRACT,null,B.DUEDATEFIRSTCONTRACT,B.DUEDATELASTCONTRACT),'dd/mm/yyyy') AS LASTCONTR,\n   CM_DECA.DueDaysCount(:RDAT , B.DUEDATEFIRSTCONTRACT,b.id) /*d.dueday*/ AS DAYSMAIN ,\n   cm_utils.Get_Gecgun_Faiz(b.id,:RDAT) AS DAYSINTRST ,\n   D.DUEINTERESTREST+D.interestrest AS OIAPERIOD ,\n   CM_DECA.OiaForLastThreeMonths(:RDAT, B.DUEDATEFIRSTCONTRACT,D.DUEINTERESTREST) AS OIATHREE , \n0 AS PROLONGS ,\n  case when  CM_DECA.DueDaysCount(:RDAT , B.DUEDATEFIRSTCONTRACT,b.id)<361 then E.CODE else '006' end AS CLASSCODE,\n   CM_DECA.Get_CreditStatus(B.ID,:RDAT )AS STATUSCODE ,\n   DECODE(G.TYPECODE,'000',null,G.TYPECODE) AS COLLCODE,\n   F.ANYINFOTODISTING AS INFDISTING,\n   D.PLEDGEPRICE  AS MARKETSUM ,\n   F.REGISTRYNO AS REGNO,\n  to_char( F.REGISTRYDATE,'dd/mm/yyyy') AS REGDATE,\n   F.REGISTRYAGENCY AS REGAGENCY\nFROM\n   CM_BOOROWERINFO A\n , CM_ACCOUNTS C\n , CM_RESERVE_TYPES E\n , CM_GUARANTEE F\n , CM_PORTFOLIO B\n , CM_PLEDGES G\n , CM_HISTORY D\n , OPERKURS O\n , AVALUTE V\n ,CM_GUARANTOR g1,CM_GUARANTOR g2,CM_GUARANTOR g3\n , CM_CATEGORIES P\nWHERE\n     (A.CREDITID = B.ID)\n AND (C.CREDITID = B.ID)\n AND (D.CREDITID = B.ID)\n AND (E.ID = D.RESERVEID)\n AND (F.CREDITID(+) = B.ID)\n AND (G.ID(+) = F.PLEDGEID)\n AND (D.HDATE=:RDAT)\n AND ((B.CLOSEDATE IS NULL) or (B.CLOSEDATE between :EDATE and :HDATE) /*(B.CLOSEDATE >=:HDATE)*/)\n AND (O.DAT=:RDAT)\n AND (O.VAL_KOD=B.CURRENCY)\n and b.id=g1.creditid(+) and g1.cardid(+)=1  and b.usrgroup<>2 and b.credittype<>15\n and b.id=g2.creditid(+) and g2.cardid(+)=2\n and b.id=g3.creditid(+) and g3.cardid(+)=3 and b.dateofgrant ıs not null \n AND (V.VALUTE=B.CURRENCY)  /*and (b.id in(select creditid from cm_tranches)or (b.credittype in(16,17))) */and b.credittype<>15\n AND (B.DATEOFCONCLUSION<=:RDAT) \n AND (P.ID = B.CUSTOMERTYPE) \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n \n\n\n\n\n\n\n\n\n\n\n\n\n\n"

# CM_DECA/DecaDataModuleImpl.dfm:777 DecaData
