SQL_DECA_ORACLEQUERY1 = 'declare\n\ncursor c_p is select * from cm_portfolio;\nbegin\n for c in c_p loop\n  update cm_guarantor set cardid=rownum where creditid=c.id;\n \n end loop;\n\nend ;'

